<?php
declare(strict_types=1);
// Page: ?page=form — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 $schema=current_schema(); $table=$_GET['table']??''; $mode=$_GET['mode']??'add'; if(!table_exists($schema,$table)) throw new RuntimeException('Table not found'); require_perm($mode==='edit'?'edit_records':($mode==='duplicate'?'duplicate_records':'create_records')); $values=[];$keys=[]; if($mode!=='add'){ $values=fetch_record($schema,$table,$_GET) ?: throw new RuntimeException('Record not found'); foreach(primary_columns($schema,$table) as $pk) $keys[$pk]=$values[$pk]; } if($_SERVER['REQUEST_METHOD']==='POST'){ $action=$mode==='edit'?'update':($mode==='duplicate'?'duplicate':'insert'); $token=make_confirmation($action,['schema'=>$schema,'table'=>$table,'mode'=>$mode,'keys'=>$_POST['keys']??[],'data'=>$_POST['data']??[],'return_to'=>'?page=table&table='.urlencode($table)]); redirect('?page=confirm&token='.$token); } layout_start(ucfirst($mode).' Record'); ?><div class="cardx"><h3><?=ucfirst(e($mode))?> in <?=e($schema.'.'.$table)?></h3><p class="text-muted">You will preview and confirm before saving.</p><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><?php render_form($schema,$table,$values,$mode,$keys);?><div class="mt-3"><button class="btn btn-primary">Preview & Confirm</button><a class="btn btn-outline-secondary" href="?page=table&table=<?=urlencode($table)?>">Cancel</a></div></form></div><?php layout_end(); exit;
